# ---------------- clash relief ----------------
ring1 = bfs_collect(bb, 17, exclude={P_idx})
ring2 = bfs_collect(bb, 23, exclude={P_idx})
bonded = set()
for b in bb.GetBonds():
    bonded.add((b.GetBeginAtomIdx(), b.GetEndAtomIdx()))
for off in (nb+3, nb+3+ncod):
    for b in cod.GetBonds():
        bonded.add((b.GetBeginAtomIdx()+off, b.GetEndAtomIdx()+off))
for p in [(nb,P_idx),(nb,Clb_i),(nb+1,Ge_idx),(nb+1,Clb_i)]:
    bonded.add(p)
for a in alk1: bonded.add((nb,a))
for a in alk2: bonded.add((nb+1,a))

def clash_metric(crds):
    tot = 0.0
    n = len(elems)
    for i in range(n):
        for j in range(i+1, n):
            if (i,j) in bonded or (j,i) in bonded: continue
            dd = np.linalg.norm(crds[i]-crds[j])
            hi = elems[i]=='H'; hj = elems[j]=='H'
            thr = 1.7 if (hi and hj) else (1.95 if (hi or hj) else 2.45)
            if dd < thr: tot += (thr-dd)**2
    return tot

def rot_set(crds, p1, p2, idxs, theta):
    a = crds[p1]; k = unit(crds[p2]-crds[p1])
    ct, st = np.cos(theta), np.sin(theta)
    out = crds.copy()
    for i in idxs:
        v = crds[i]-a
        out[i] = a + v*ct + np.cross(k, v)*st + k*np.dot(k, v)*(1-ct)
    return out

cod1_idx = list(range(nb+3, nb+3+ncod))
cod2_idx = list(range(nb+3+ncod, nb+3+2*ncod))
m1 = unit(-(u_P+u_Cl1)); m2 = unit(-(u_Ge+u_Cl2))

cur = clash_metric(coords)
print("start metric:", round(cur,2))
for _ in range(2):
    for (p1,p2,idxs) in [(P_idx,17,ring1),(P_idx,23,ring2)]:
        bestloc = (cur, 0.0, coords)
        for th in np.linspace(0, 2*np.pi, 24, endpoint=False):
            c2 = rot_set(coords, p1, p2, idxs, th)
            m = clash_metric(c2)
            if m < bestloc[0]: bestloc = (m, th, c2)
        cur, _, coords = bestloc
    for (IrI, mdir, idxs) in [(Ir1_i, m1, cod1_idx), (Ir2_i, m2, cod2_idx)]:
        bestloc = (cur, 0.0, coords)
        for th in np.linspace(-np.pi/2, np.pi/2, 19):
            c2 = rot_set(coords, IrI, IrI+mdir, idxs, th)
            m = clash_metric(c2)
            if m < bestloc[0]: bestloc = (m, th, c2)
        cur, _, coords = bestloc
    print("metric now:", round(cur,3))

write_xyz("initial.xyz", elems, coords, "assembled complex (clash-relieved)")

# report residual worst contacts
rep = []
n = len(elems)
for i in range(n):
    for j in range(i+1, n):
        if (i,j) in bonded or (j,i) in bonded: continue
        dd = np.linalg.norm(coords[i]-coords[j])
        hi = elems[i]=='H'; hj = elems[j]=='H'
        thr = 1.6 if (hi and hj) else (1.8 if (hi or hj) else 2.2)
        if dd < thr: rep.append((dd, elems[i], i, elems[j], j))
rep.sort()
print("residual close contacts:", len(rep))
for w in rep[:10]: print(f"  {w[0]:.2f} {w[1]}:{w[2]} - {w[3]}:{w[4]}")
print("Ir1-P:", round(np.linalg.norm(coords[Ir1_i]-coords[P_idx]),3),
      "Ir2-Ge:", round(np.linalg.norm(coords[Ir2_i]-coords[Ge_idx]),3),
      "Ir1-Clb:", round(np.linalg.norm(coords[Ir1_i]-coords[Clb_i]),3),
      "Ir2-Clb:", round(np.linalg.norm(coords[Ir2_i]-coords[Clb_i]),3))
for I, alk in ((Ir1_i, alk1), (Ir2_i, alk2)):
    print("Ir-C:", [round(float(np.linalg.norm(coords[I]-coords[a])),2) for a in alk])
